uniform float speed : 0.0 .. 5.0 = 1.0;      // sweep rate (turns of the column per second)
uniform float width : 0.01 .. 0.4 = 0.08;      // beam width as a fraction of the column
uniform float dark : 0.0 .. 1.0 = 0.06;        // dim tail level of the unlit column
uniform vec3 tint : color = 0.3, 0.8, 1.0;     // beam colour
uniform bool bounce = false;                   // ping-pong instead of wrapping

state fixed head;      // beam position along the column, TURNS 0..1
state fixed dir;       // sweep direction for bounce mode

void update() {
  fixed step = fixed(dt * speed);
  if (bounce) {
    head = head + step * dir;
    if (head >= fixed(1.0)) { head = fixed(1.0); dir = -fixed(1.0); }
    if (head <= fixed(0.0)) { head = fixed(0.0); dir =  fixed(1.0); }
  } else {
    head = fract(head + step);
  }
}

vec3 shade(Led led) {
  // column coordinate 0..1 (bottom -> top) from the LED's own position
  fixed y = clamp(fixed(led.pos.y) / fixed(0.3), fixed(0.0), fixed(1.0));
  fixed d = y - head;                                   // signed distance to the beam core
  fixed core = clamp(fixed(1.0) - abs(d) / fixed(width), fixed(0.0), fixed(1.0));
  fixed glow = core * core;                             // sharpen the beam
  fixed halo = clamp(fixed(1.0) - abs(d) / (fixed(width) * fixed(3.0)), fixed(0.0), fixed(1.0));
  fixed v = dark + glow + halo * fixed(0.25);           // beam + soft halo + faint column
  return tint * float(v);
}
